-- RAJDOOT canonical embassy registry seed generated from 123.xlsx.
-- Review was confirmed in chat before this seed was prepared.
begin;

-- Canonical active embassy registry.

on conflict (country_key) do update set country_name=excluded.country_name, channel_id=excluded.channel_id, channel_name=excluded.channel_name, category_id=excluded.category_id, status='active', display_order=excluded.display_order, updated_at=now();

on conflict (country_key) do update set status='archived', archive_reason=excluded.archive_reason, display_order=null, updated_at=now();

-- Legacy role reconciliation. Six orphan roles are retained as pending deletion until access safety is verified.

on conflict (role_id) do update set embassy_id=excluded.embassy_id, role_name=excluded.role_name, disposition=excluded.disposition, notes=excluded.notes, updated_at=now();

update embassies e
set legacy_access_role_id=r.role_id, updated_at=now()
from (
    select embassy_id, min(role_id) role_id
    from embassy_legacy_roles
    where embassy_id is not null and disposition='mapped'
    group by embassy_id
) r
where e.id=r.embassy_id;

update embassies set display_order=null, updated_at=now() where status='archived';

commit;
